from pathlib import Path
import json,re
root=Path.cwd()
helpdir=root/'help'
chapters={
'start':('index.html','开始使用', '''<p>本地手册适用于 KinSealStudio Lite 0.11.0 便携版。帮助可离线使用，不需要安装原厂软件或打开浏览器。</p><ol><li>新建工程并确认型号、分辨率与连接。</li><li>新建或切换画面，放置控件，设置地址、文本和外观。</li><li>先保存 .ksp，再按当前支持范围导出原厂源工程或编译设备包。</li><li>下载后检查屏幕标识和实际触控。保存编译、传输和观察结果。</li></ol><p>菜单中仍有范围提示入口。能编辑或保存某个控件，不代表该控件所有运行功能已经在实物上验证。</p><p>F1 打开当前窗口的有限上下文帮助；无法识别的窗口回到目录。原有部分“帮助”按钮仍显示该控件的简要说明。新帮助未覆盖所有右键、双击、嵌套字段和错误入口。</p><p>安装器、升级和卸载流程本版未提供；请保留完整便携目录。已有 USB 驱动和宏 SDK 为外部依赖，包内不自动安装它们。</p>'''),
'project':('project.html','工程、型号与画面', '''<h2 id="new">建立工程</h2><p>使用“新建工程”，选择实际触摸屏对应的型号和分辨率。当前设备格式以已验证的 AMT 800×480 范围为主。LT779、未知固件或其他分辨率不能直接沿用已有通过结论。</p><p>通过工程与画面设置管理页面、顺序、启动页和启动语言。画面支持新增、改名、复制、删除及切换；先检查引用，再确认修改。取消会放弃当前草稿。</p><h2 id="connections">连接与地址</h2><p>先配置连接，再在控件中选择设备、地址区和数据类型。LB/LW 为内部地址。PLC 地址目录可帮助选择，但目录有该型号不等于串口驱动和设备通信已逐一实现。</p><p>多页可以编辑和保存；当前设备编译、源导出及模拟各有自己的边界，多页、窗口和未恢复的活动系统配置可能在执行前被拒绝。不要删去配置来掩盖错误，应保留原工程另存受支持测试副本。</p><p>全局文字、地址、控件和宏一览可用于定位；地址替换先预览，确认后作为一次工程修改。撤销、重做与保存状态跟随工程事务。</p>'''),
'controls':('controls.html','控件与属性', '''<h2 id="placement">放置与修改</h2><p>从控件菜单或工具箱选择控件。需要属性的控件先完成属性窗口，再在画布拖出区域；线条和静态图形按其绘制步骤放置。Esc 取消当前放置。双击已有控件可再次编辑，右侧属性栏用于通用几何与选中项。</p><p>属性“确定”会先校验地址、状态、尺寸、资源和引用，成功后才写回；校验提示未消失时继续修正。取消不应把草稿写回工程。嵌套图片、宏或地址窗口先确认内层，再确认外层；外层取消时不应把临时选择当作已保存。</p><h2 id="bit-word">位按钮、字按钮与指示灯</h2><p>位按钮按所选操作控制位值，字按钮按类型与操作写入数值。指示灯用监控地址选择显示状态；监控地址可独立于按钮地址。请核对 LB/LW、数据宽度和状态上限，32位值占两个字。</p><p>阶段10实屏已确认：LB0反转、LB1置位/复位、LB2按住置位及松开复位；LW20指定写0/1/4和LW30指定写0/3由独立灯观察。它们不等于字按钮全部操作、完整U32高字/字序、32态灯、失焦/移出释放和长期稳定已验。</p><h2 id="resources">图片、文本与其他控件</h2><p>文本按工程语言分别配置，启动语言与编辑预览语言不同。图片先从工程图库或系统图库选择，确认状态对应的外观；图库预览成功不等于任何外部资源都可无条件重新分发。</p><p>数值、ASCII、消息、GIF、趋势、报警、采集、历史、配方等有独立属性与引用条件；部分可编辑而设备编码或运行语义仍受限制。出现“后续阶段”或“不支持”提示时，当前功能尚未在该路径开放，不能仅靠补一个数据源保证可用。</p><p>静态图形和表格的图像显示不代表配方、历史或数据表的动态读取已实现。自由线、折线和圆弧的采用行为按当前样例与限制表核对。</p><h2 id="permissions">权限、显现与功能</h2><p>显现条件决定是否显示；权限、通知与按压是不同设置，不可互相代替。阶段10已确认LB41显隐及出现后触控。语言切换和LB40通知的最终组合观察仍待用户确认，其余权限/闪烁/跨页和配置运行项仍有未验。</p>'''),
'files':('files.html','保存、格式与备份', '''<h2 id="ksp">保存工程</h2><p>日常编辑保存为 .ksp。当前程序接受 schema 1～12，写入版本随实际使用字段选择，不能手改版本号绕过未知字段检查。新字段可能使旧程序拒绝打开；升级前保留原文件并另存新副本。</p><p>多页、语言、连接、资源和宏等按工程模型保存；运行模拟中的数值不会自动写回工程。设备运行值保持与断电保持尚未闭合验收。</p><h2 id="sm">原厂 .sm 与设备文件</h2><p>受支持的原厂 .sm 可导入编辑；“导出原厂工程”写原厂源格式的受支持范围。未知结构保留策略或拒绝提示以实际导入结果为准，不能把可打开的未知快照当作全部语义已经解析。</p><p>.ksp、原厂 .sm 和设备编译产物不是同一种文件。Lite JSON 快照不能改扩展名冒充原厂源工程。.kns 等设备文件按编译和传输入口使用。</p><p>修改宏源码后，原厂导出工程会按规则标记相关缓存未编译；应重新编译，不能把旧机器码与新源码混用。导出失败保留原 .ksp，不覆盖已知成功包。</p>'''),
'compile':('compile.html','设备编译与宏', '''<h2 id="device">设备编译</h2><p>先保存或核对当前工程，再执行受支持编译/下载入口。编译会校验页面、对象、地址、动态区域、资源与系统配置。保存成功只能说明工程格式有效；设备编译还要通过独立的能力检查。</p><p>透明按钮覆盖动态对象、动态文本与其他控件重叠等未闭合组合会被拒绝；图片的透明度也参与检查。多页/窗口和未恢复的活动配置不因能保存就获得下载资格。遇到拒绝请按提示定位控件，另存最小样例，再逐项增回。</p><h2 id="macro">宏编辑与外部 SDK</h2><p>使用宏编辑/管理查看源码、引用与编译诊断；使用工具链设置显式选择自己的兼容 SDK。普通编辑和无宏流程不需要 SDK。宏库示例是源码参考，不能当作完整设备编译器。</p><p>缺 SDK、工具退出失败或诊断错误时不得沿用旧编译成功状态。源码、SDK身份和编译结果需对应。宏反编译、任意C语义仿真和所有运行时接口没有完整支持承诺。</p><p>离线模拟不执行设备宏。真实设备宏的成功传输与执行观察要分别记录。</p>'''),
'usb':('usb.html','下载、上载、介质与恢复', '''<h2 id="download">普通工程下载</h2><p>先保存工程，确认 USB 设备和目标，关闭其他占用工具，再使用“下载工程”。本版不随包安装系统 libusb0 驱动；未检测设备或驱动缺失时按提示处理，不要把未知设备当作已连接成功。</p><p>下载会校验编译包并执行传输、提交和重启收尾。提交/重启成功后仍要看实屏标识，并测试独立观察的数值和触控；USB ACK 不能证明画面或PLC运行正确。</p><h2 id="other">上载、升级和介质</h2><p>上载、固件升级、介质制作及屏内原工程备份没有本版完整交付承诺；入口显示范围提示时请停止该流程，保留现有工程和旧包。不要把普通工程下载作为固件升级，也不要把测试工程重下当成屏内工程上载备份。</p><h2 id="restore">失败与恢复</h2><p>下载失败保留日志、工程与已知成功包，记录屏幕当前标识。设备状态不明时先重新检测，不反复覆盖未知内容。本版没有通用自动回滚承诺。</p><p>本次现场宏14样例曾重新下载并由用户确认恢复标识和按钮；随后切换到了阶段10功能测试页，当前通知/语言组合仍待反馈，第二次恢复尚未执行。该测试页恢复不是屏内原工程与运行值的备份。</p><p>出现“控件宽度不够，无法显示”时先核对实屏标识是否为刚下载工程、提交与重启是否完整，再检查控件几何和编码。不要只根据旧页面提示重复修改新工程宽度。</p>'''),
'simulation':('simulation.html','离线模拟与PC串口', '''<h2 id="offline">离线模拟</h2><p>“离线模拟”基于当前编辑内容建立独立快照。当前有限支持单个800×480普通画面、内部LB/LW和已支持基础控件及指定系统功能。点击操作、数值输入和内部地址观察只发生在模拟会话；关闭后运行值不保存回工程。</p><p>多页、外部地址、活动采集/报警/历史/配方及未核时序在启动前拒绝。宏不执行。PC首帧和操作测试不能替代真实触摸屏执行。</p><h2 id="pcserial">PC串口调试</h2><p>在线菜单打开独立“PLC通信与协议能力”工具。必须显式选择或输入PC串口，核对波特率、校验、停止位、从站与超时，再执行单次Modbus RTU请求。地址按0起始PDU填写，写入前核对实际设备允许的地址和值。</p><p>现有读01/02/03/04、写05/06/15/16按工具范围执行；工程画面与PC串口自动联动尚未开放。目录中的原厂协议与地址编码资料不等于全部PC协议驱动可用。未连接真实PLC时，回放和模拟结果仍只属于PC验证。</p><p>取消会等待会话收尾；不要在旧请求仍运行时立即重复写。真实PLC联调需实际端点和独立读回，本轮未凭空补齐。</p>'''),
'limits':('limits.html','限制与常见提示', '''<h2 id="scope">如何理解支持范围</h2><p>界面可用、工程可保存、画面可渲染、设备可编译、USB可传输和设备实际运行是不同结果。本版为范围受限的便携发布，不能称完整原厂复刻。</p><p>阶段10的真实设备固件版本和唯一硬件序列号仍未确认；USB回复中的日期样字符不能当固件版本。PLC、保持/断电、上载、长期性能、跨页配置与部分权限行为仍有欠项。</p><h2 id="messages">为什么弹窗</h2><ul><li>“后续阶段完成”：该入口保留外观，操作实现尚未开放，当前操作不应修改工程。</li><li>属性校验：字段组合、地址、资源或引用不满足要求；修改后再确定，或取消保留原工程。</li><li>设备编译不支持：工程编辑支持范围大于设备编码范围，补数据不一定能解决；按提示保留最小复现。</li><li>驱动/设备/SDK缺失：按场景配置外部依赖；普通编辑应继续可用。</li><li>帮助缺失/索引损坏：从同版本便携包恢复help目录，或关闭帮助继续工作。帮助不访问互联网。</li></ul><h2 id="unverified">未覆盖入口</h2><p>命令映射是帮助路由表，不是功能全部完成证明。未明确说明的右键、双击、嵌套窗口、错误分支和历史原生入口仍需逐项核查。原有部分帮助按钮保留简要提示，F1采用有限窗口映射。用户手册不公开反编译偏移，也不照搬旧CHM为能力承诺。</p>''')}
nav='<p>'+' | '.join(f'<a href="{file}">{title}</a>' for file,title,_ in chapters.values())+'</p>'
for topic,(file,title,body) in chapters.items():
    (helpdir/file).write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>'+title+'</title><style>body { font-family: Microsoft YaHei, sans-serif; font-size: 11pt; color:#222; } h1 { color:#16406b; } h2 { color:#244f76; } p,li { line-height:1.5; } a { color:#1b5e9a; }</style></head><body><h1>'+title+'</h1>'+nav+body+'<hr><p>KinSealStudio Lite 0.11.0 · 本地操作手册 · 2026-11-14</p></body></html>\n',encoding='utf-8')
layout=json.loads((root/'resources/native-shell/layout.json').read_text(encoding='utf-8'))
commands={k:{'label':v['text'],'topic':'limits','capability':'保留原生入口；本帮助未逐项确认该命令实现范围，以界面守卫和限制提示为准。','coverage':'routing-only'} for k,v in layout['actions'].items()}
for source_name in ('src/main_window.cpp','src/native_shell_ui.cpp'):
    for key in re.findall(r'QStringLiteral\(\"(action_[A-Za-z0-9_]+|ShellQuickProperties)\"\)',(root/source_name).read_text(encoding='utf-8-sig')):
        commands.setdefault(key,{'label':key,'topic':'limits','capability':'本帮助未逐项确认该入口的完整范围，以界面守卫和限制提示为准。','coverage':'routing-only'})
extra={'action_H':'帮助','action_detect_device':'检测USB下载设备','action_export_native':'导出原厂工程','action_connections':'PLC连接设置','action_macro_sdk':'ARM宏工具链设置','action_project_settings':'工程与画面设置','action_languages':'工程语言'}
for k,v in extra.items(): commands.setdefault(k,{'label':v})
def group(ids,topic,capability):
    for id in ids.split():
        
        if id in commands: commands[id].update(topic=topic,capability=capability,coverage='chapter-summary')
group('action_H action_Help action_h action_KinSeal action_version','start','打开本地帮助目录或当前版本说明；并非全入口完成证明。')
group('action_new_pro action_open_pro action_close action_project_settings action_connections action_languages action_screen_table action_newscreen action_upscreen action_nextscreen action_TextView action_address_table action_address_find action_items_table','project','工程/页面/连接/语言编辑与定位；确认与取消按工程事务；设备能力仍单独检查。')
group('action_save action_save_as action_export_native','files','KSP保存及受支持原厂源格式导出；schema与未知结构按校验，不改变扩展名冒充格式。')
group('action_undo action_redo action_cut action_copy action_paste action_delete action_selectall action_checkall action_copym action_grid action_ungroup action_sendtoback action_sendbackward ShellQuickProperties action_project_pictures action_bringtop action_sengtoback action_bringforward action_bringback action_left action_right action_top action_under action_horizontal action_vertcal action_hcenter action_vcenter action_widthsame action_heightsame action_widthheightsame action_openpropertiset action_lock action_delock action_group action_split action_zoonfit action_zoonbig action_zoonsmall','controls','画布选择、几何、层次、属性及撤销工作流；原生组节点、锁定/镜像等仍按已有范围检查。')
group('action_text action_bitBtn action_wordbutton action_lamp action_funbutton action_messagedisplay action_mark action_qrcode pictruedisplay action_GIFoutput action_dataDisplay action_asciiDisplay action_timeDisplay action_screenbutton action_polyBtn action_MFbtn action_droplist action_flow_block action_Slider action_wheelView action_moveTrack graphicsitem action_trendchart action_DatagroupDisplay action_X_Y action_dataGroup action_dynamicarlarm action_histotyarlarm action_arlamcontrol action_historyrecord action_recipetable action_line action_rect action_ellipse action_RoundedRect action_foldline action_polygon action_freeline action_ArcItem action_table action_rep action_datasamp','controls','独立控件/配置编辑、字段校验及资源引用；可编辑不代表全部原生源/设备编码/运行功能已闭合。')
group('action_script action_macro_admin action_macro_find action_GlobalMacro action_InitMacro action_macro_sdk action_compile','compile','宏源码/引用/外部SDK及设备编译范围；无SDK或不支持布局明确拒绝。')
group('action_USBdownload action_detect_device action_detect_device action_upload action_usbdriver action_upgrade action_upgrade2','usb','普通工程下载与依赖检测；上载/固件升级/介质及自动回滚未提供完整交付承诺。')
group('action_offline_simulation action_online_simulation','simulation','内部地址快照离线模拟与显式PC Modbus RTU工具；不自动联动工程画面，不代替实物PLC。')
contexts=[]
for title,topic in [('图库','controls'),('图片','controls'),('宏','compile'),('PLC','simulation'),('地址输入','project'),('工程','project'),('画面','project'),('语言','project'),('下载','usb'),('设备','usb')]: contexts.append({'titleContains':title,'topic':topic})
# Exact property dialog names precede title fallbacks; nested address and macro dialogs retain their own topic.
control_names=['BitButtonDialog','StaticTextDialog','MessageDisplayDialog','ScaleDialog','QrCodeDialog','GifDisplayDialog','NumberDisplayDialog','AsciiDisplayDialog','TimeDisplayDialog','ScreenButtonDialog','MultiStateButtonDialog','MultiFunctionButtonDialog','DropdownDialog','FlowBlockDialog','SliderDialog','WheelDialog','MoveTrackDialog','ChartDialog','TrendDialog','HistoryTrendDialog','XyCurveDialog','DataGroupDialog','AlarmBarDialog','AlarmDisplayDialog','HistoryDataDialog','RecipeDisplayDialog','GraphicDialog']
contexts=[{'objectName':n,'topic':'controls'} for n in control_names]+[{'objectName':'PlcOnlineDialog','topic':'simulation'},{'objectName':'MacroManagerDialog','topic':'compile'}]+contexts
catalog={'schemaVersion':1,'productVersion':'0.11.0','coverageNote':'显式命令路由与有限F1/WhatsThis上下文；保留原有部分帮助按钮。未审全右键/双击/嵌套字段/错误入口，不声明全D/U。','topics':{k:{'file':v[0],'title':v[1]} for k,v in chapters.items()},'commands':dict(sorted(commands.items())),'contexts':contexts}
(helpdir/'command-map.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps({'topics':len(chapters),'commands':len(commands),'contexts':len(contexts)},ensure_ascii=False))
